enum DevicePlatform { ios, android, windows, macos, linux }

class UserAccount {
  final String id;
  final String name;
  final String email;
  final String storeId;
  final String storeName;
  final String role; // Store Owner, Cashier, Inventory Manager
  final String token;

  const UserAccount({
    required this.id,
